// 8个LED流水灯(PA0-PA7)
#include "main.h"

const uint16_t ledPins[] = {
    GPIO_PIN_0, GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3,
    GPIO_PIN_4, GPIO_PIN_5, GPIO_PIN_6, GPIO_PIN_7
};

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();

    while (1) {
        for (int i = 0; i < 8; i++) {
            // 先全灭
            for (int j = 0; j < 8; j++) {
                HAL_GPIO_WritePin(GPIOA, ledPins[j], GPIO_PIN_RESET);
            }
            // 点亮当前LED
            HAL_GPIO_WritePin(GPIOA, ledPins[i], GPIO_PIN_SET);
            HAL_Delay(200);
        }
    }
}

// 双向流水灯
void flowForward(void) {
    for (int i = 0; i < 8; i++) {
        allOff();
        HAL_GPIO_WritePin(GPIOA, ledPins[i], GPIO_PIN_SET);
        HAL_Delay(200);
    }
}

void flowBackward(void) {
    for (int i = 7; i >= 0; i--) {
        allOff();
        HAL_GPIO_WritePin(GPIOA, ledPins[i], GPIO_PIN_SET);
        HAL_Delay(200);
    }
}

// 主循环
while (1) {
    flowForward();
    flowBackward();
}

// 软件PWM呼吸灯
void softPWM(uint8_t brightness) {
    // brightness: 0-100
    uint16_t onTime = brightness;     // 亮的时间(单位us)
    uint16_t offTime = 100 - brightness;

    HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_RESET);  // 亮
    for (volatile int i = 0; i < onTime * 10; i++);
    HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_SET);    // 灭
    for (volatile int i = 0; i < offTime * 10; i++);
}

// 呼吸效果
while (1) {
    // 渐亮
    for (int b = 0; b <= 100; b += 5) {
        for (int j = 0; j < 10; j++) softPWM(b);
    }
    // 渐灭
    for (int b = 100; b >= 0; b -= 5) {
        for (int j = 0; j < 10; j++) softPWM(b);
    }
}

// 综合示例：LED多种效果
#include "main.h"

void ledBlink(int times, int delay) {
    for (int i = 0; i < times; i++) {
        HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);
        HAL_Delay(delay);
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();

    while (1) {
        ledBlink(10, 200);  // 快闪10次
        HAL_Delay(1000);     // 停1秒
        ledBlink(3, 1000);   // 慢闪3次
        HAL_Delay(1000);
    }
}
